{"command": "cd ~/ctrl; python3 - <<'EOF'
s = open("controller.py").read()
s = s.replace("""    p = servo_tip(arm, hole, tol=0.7, iters=4)
    if p["tilt"] > 2.5: straighten(arm, p)
""", """    if p["tilt"] > 2.5: straighten(arm, p); _, p = locate()
    p = servo_tip(arm, hole, tol=0.7, iters=4)
    if p["tilt"] > 4.0: straighten(arm, p); servo_tip(arm, hole, tol=0.8, iters=2)
""")
s = s.replace("""            if p["z"] < top - 3: straighten(arm, p)
            else: servo_tip(arm, hole, tol=0.6, iters=3)
""", """            if p["tilt"] > 2.0: straighten(arm, p)
            if p["z"] >= top - 3: servo_tip(arm, hole, tol=0.6, iters=3)
""")
open("controller.py","w").write(s)
EOF
python3 -c "import ast;ast.parse(open('controller.py').read())" && trial start && python3 controller.py 2>&1 | tee trial3.log | grep -E "^(A|B|RESULT|   (cap|peg|lifted|SEATED|FAILED|stall|final|tip z|straighten))"; trial end", "timeout": 400}

